import pytest


def age_at(born: int, now: int) -> int:
    """Whole years from the birth year `born` to the current year `now`.

    `now` is supplied by the caller; this function must not read the clock.
    Returns `now - born`. Raises ValueError if `now < born`.
    """
    if now < born:
        raise ValueError(f"now ({now}) is before born ({born})")
    return now - born


def test_age_at_later_year() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_at_born_after_now_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2030, 2024)
